/**
 * The Sign
 * ----------
 * Gideon prepares a young goat and unleavened cakes; fire consumes the offering on the rock and the angel vanishes. Stage: a rock at the oak's shade, a meat offering on a stone, a flame rising from it; the terrified Gideon; the morning lit by one sudden fire.
 *
 * Palette 0x1a0e08 → 0x0a0502 · light: ember · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./gideon-kit.js.
 */

import { THREE, createScene, oak, flame, sheep, pillar, person } from './gideon-kit.js';

const BG = 0x1a0e08;
const GROUND = 0x0a0502;

export function build(group) {
    const W = createScene(group, { seed: 3894556654, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x0a0502, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* trees: broadleaf shade */
    oak(W, group, -72.2, 0, -14.3, 1.37, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -36.0, 0, -36.1, 0.96, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, -57.6, 0, 6.0, 0.99, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });
    oak(W, group, 66.9, 0, 1.5, 1.13, { leaf: 0x4f8a2e, leaf2: 0x5fa036 });

    /* fire: the burning mark */
    flame(W, group, -7.9, 0, 1.2, 1.1);
    W.point(0xff8a30, 2.0, 55, 0, 3, 0, 0.35);

    /* flock: sheep grazing */
    sheep(W, group, -9.9, 0, 5.4, W.r() * 6, 1.11);
    sheep(W, group, -16.4, 0, 3.9, W.r() * 6, 1.06);
    sheep(W, group, -12.7, 0, -7.2, W.r() * 6, 1.18);
    sheep(W, group, -15.9, 0, -0.2, W.r() * 6, 1.13);

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x0a0502 });
    W.disc([0, 6, -12], 5, 0x22120a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x1a0e08, ry: 0.42, s: 1.16 });
    person(W, group, [4.5, 0, 6], { robe: 0x0a0502, ry: -0.15, s: 1.05 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, ry: -0.03, s: 1.13 });

    return W.finish();
}

export default { build };
